#!/usr/bin/env python3
"""Stream a Claude Code JSONL transcript and emit flattened records."""
import json, sys, re

def flatten(path):
    """yield dicts: idx, ts, role, kind, name, text"""
    with open(path, errors='replace') as f:
        for idx, line in enumerate(f):
            line = line.strip()
            if not line:
                continue
            try:
                d = json.loads(line)
            except Exception:
                continue
            ts = d.get('timestamp', '')
            msg = d.get('message')
            if not isinstance(msg, dict):
                continue
            role = msg.get('role', d.get('type', ''))
            content = msg.get('content')
            if isinstance(content, str):
                yield dict(idx=idx, ts=ts, role=role, kind='text', name='', text=content)
                continue
            if not isinstance(content, list):
                continue
            for b in content:
                if not isinstance(b, dict):
                    continue
                t = b.get('type')
                if t == 'text':
                    yield dict(idx=idx, ts=ts, role=role, kind='text', name='', text=b.get('text',''))
                elif t == 'thinking':
                    yield dict(idx=idx, ts=ts, role=role, kind='thinking', name='', text=b.get('thinking',''))
                elif t == 'tool_use':
                    yield dict(idx=idx, ts=ts, role=role, kind='tool_use', name=b.get('name',''),
                               text=json.dumps(b.get('input', {}), ensure_ascii=False))
                elif t == 'tool_result':
                    c = b.get('content')
                    if isinstance(c, list):
                        c = '\n'.join(x.get('text','') for x in c if isinstance(x, dict))
                    yield dict(idx=idx, ts=ts, role='tool', kind='tool_result', name='',
                               text=c if isinstance(c, str) else json.dumps(c)[:4000])

